/**
 * Token addresses and decimals of the Keeta stablecoins, per network.
 * Generated by `npm run assets:pin` (needs the Keeta network): it resolves
 * each `$K` token through the network's anchor resolver and reads its
 * decimals and symbol from the token's own ledger info.
 *
 * A stablecoin that is not pinned here is listed as "not yet available": the
 * apps cannot buy credits with it or cash out to it, the FX provider does not
 * trade it, and the router does not ask for it. USDC is pinned in assets.ts.
 */

import type { NetworkName } from './constants.ts';

export interface AssetPin {
	/** Token address on Keeta. */
	address: string;
	/** Decimal places, from the token's metadata on the ledger. */
	decimals: number;
}

export const ASSET_PINS: Record<NetworkName, Partial<Record<string, AssetPin>>> = {
	"test": {},
	"main": {}
};
